const fs = require('fs-extra');
/**
 * 验证并返回JSON对象
 * @param {string} filePath JSON文件路径
 * @returns {content:Object|null, error:Exception|null} 验证通过返回JSON对象，否则返回null和错误信息
 */
function validateJsonAndReturn(filePath) {
    try {
        // 读取JSON文件内容
        const jsonContent = fs.readFileSync(filePath, 'utf8');
        // 解析JSON字符串为JavaScript对象
        const jsonObject = JSON.parse(jsonContent);

        // 遍历JSON对象的每个键值对进行验证
        for (const [key, value] of Object.entries(jsonObject)) {
            // 验证key是否为字符串类型
            if (typeof key !== 'string') {
                throw new Error(`错误: key "${key}" 不是字符串类型`);
            }
            // 验证value是否为对象类型
            if (typeof value !== 'object' || value === null) {
                throw new Error(`错误: "${key}" 的值不是对象类型`);
            }

            // 解构value对象,获取需要验证的属性
            const { IsFolder, Define, Type, NewName, Context } = value;

            // 验证IsFolder属性
            if (IsFolder !== undefined) {
                if (typeof IsFolder !== 'boolean') {
                    throw new Error(`错误: "${key}" 的 IsFolder 属性不是布尔类型`);
                }
                // Define 必须为bool
                // 验证Define属性
                if (Define !== undefined) {
                    if (typeof Define !== 'boolean') {
                        throw new Error(`错误: "定义了 'IsFolder=true' 以后, Define 属性必须为布尔类型`);
                    }
                }
                if (NewName !== undefined) {
                    throw new Error(`错误: "定义了 'IsFolder=true' 以后, 不能定义 'NewName' 属性`);
                }
            }

            // 验证Type属性 必须为 Module|Instance|Factory
            if (!['Module', 'Instance', 'Factory', 'Impl'].includes(Type)) {
                throw new Error(`错误: "${key}" 的 Define 属性必须是 'Module'、'Instance'、'Factory'  之一`);
            }

            // 验证Context属性 必须为 Server|Client 或者 undefined
            if (Context !== undefined) {
                if (!['Server', 'Client'].includes(Context)) {
                    throw new Error(`错误: "${key}" 的 Context 属性必须是 'Server' 或 'Client' 之一`);
                }
            }
        }

        // 所有验证通过,返回解析后的JSON对象
        return { content: jsonObject, error: null };
    } catch (error) {
        // 捕获并返回读取或解析JSON文件时的错误
        console.error(`解析JSON文件时出错,位置 ${filePath}:`, error);
        return { content: null, error: error };
    }
}

module.exports = validateJsonAndReturn;
